module CHIP (
	clk, 
	rst_n, 
	in_valid, 
	in_valid2, 
	in_data, 
	out_valid, 
	out_sad);
   input clk;
   input rst_n;
   input in_valid;
   input in_valid2;
   input [8:0] in_data;
   output out_valid;
   output out_sad;

   // Internal wires
   wire C_clk;
   wire C_rst_n;
   wire C_in_valid;
   wire C_in_valid2;
   wire [8:0] C_in_data;
   wire C_out_valid;
   wire C_out_sad;

   MVDM CORE (.clk(C_clk),
	.rst_n(C_rst_n),
	.in_valid(C_in_valid),
	.in_valid2(C_in_valid2),
	.in_data(C_in_data),
	.out_valid(C_out_valid),
	.out_sad(C_out_sad));
   XMD I_CLK (.O(C_clk),
	.I(clk),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_RSTN (.O(C_rst_n),
	.I(rst_n),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INVALID (.O(C_in_valid),
	.I(in_valid),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INVALID2 (.O(C_in_valid2),
	.I(in_valid2),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INDATA0 (.O(C_in_data[0]),
	.I(in_data[0]),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INDATA1 (.O(C_in_data[1]),
	.I(in_data[1]),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INDATA2 (.O(C_in_data[2]),
	.I(in_data[2]),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INDATA3 (.O(C_in_data[3]),
	.I(in_data[3]),
	.PU(1'b0),
	.PD(1'b0),
	.SMT(1'b0));
   XMD I_INDATA4 (.O(C_in_data[4]),
	.I(in_data[4]),
